def solution(data=None):
    import sys

    if data is None:
        input = sys.stdin.readline
    else:
        it = iter(data.strip().split())
        input = lambda: next(it, "")

    n = int(input())
    q = int(input())

    lr = []
    for _ in range(q):
        l = int(input())
        r = int(input())
        lr.append((l, r))

    # coverage prefix
    cov = [0] * (n + 3)
    for l, r in lr:
        cov[l] += 1
        cov[r + 1] -= 1
    for i in range(1, n + 1):
        cov[i] += cov[i - 1]

    total = 0
    one = [0] * (n + 2)
    two = [0] * (n + 2)
    for i in range(1, n + 1):
        if cov[i] > 0:
            total += 1
        one[i] = one[i - 1] + (1 if cov[i] == 1 else 0)
        two[i] = two[i - 1] + (1 if cov[i] == 2 else 0)

    # unique coverage per painter
    unique = [0] * q
    for idx, (l, r) in enumerate(lr):
        unique[idx] = one[r] - one[l - 1]

    # count positions with cov==2 shared by painter pairs
    # since n,q <= 5000, O(n*q) is acceptable (~25M checks)
    two_pair = {}
    for pos in range(1, n + 1):
        if cov[pos] == 2:
            a = -1
            b = -1
            for idx, (l, r) in enumerate(lr):
                if l <= pos <= r:
                    if a == -1:
                        a = idx
                    else:
                        b = idx
                        break
            if a > b:
                a, b = b, a
            key = (a, b)
            two_pair[key] = two_pair.get(key, 0) + 1

    max_loss = 0
    for i in range(q):
        ui = unique[i]
        for j in range(i + 1, q):
            loss = ui + unique[j] + two_pair.get((i, j), 0)
            if loss > max_loss:
                max_loss = loss

    result = total - max_loss
    if data is None:
        print(result)
    else:
        return result

